var workflow = AgentWorkflowBuilder.BuildConcurrent([researcher, marketer, legal]);

var messages = new List<ChatMessage> { new(ChatRole.User, "We launch a budget eBike for commuters.") };
await using StreamingRun run = await InProcessExecution.RunStreamingAsync(workflow, messages);
await run.TrySendMessageAsync(new TurnToken(emitEvents: true));
await foreach (WorkflowEvent evt in run.WatchStreamAsync())
    if (evt is AgentResponseUpdateEvent e) Console.WriteLine($"{e.ExecutorId}: {e.Update.Text}");
